mapper.select:
select c2.c_name as pprBusinessUnitName, c3.c_name as pprReserveCpyName, mn.*, d1.d_name as pprManagerUnitName, sys.d_name as pprManagerDepName, u1.U_Name as pprProjectManagerName, u2.U_Name as pprProjectLeaderName, u3.U_Name as pprEngineerName, u4.U_Name as pprEngineerLeaderName, pp.P_ID as projectId, pp.State as projectState from Pre_Project_Reserve mn left join sys_department d1 on d1.d_id=mn.ppr_manager_unit left join sys_company c2 on c2.c_id=mn.ppr_business_unit left join sys_company c3 on c3.c_id=mn.ppr_Reserve_cpy left join sys_department sys on mn.ppr_Manager_Dep = sys.d_id left join SYS_User u1 on u1.u_id=mn.ppr_project_manager left join SYS_User u2 on u2.u_id=mn.ppr_project_leader left join SYS_User u3 on u3.u_id=mn.ppr_engineer left join SYS_User u4 on u4.u_id=mn.ppr_engineer_leader left join Pre_Project pp on pp.ppr_id=mn.id
order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc

mapper.sql:
    ${authSql}
    
        and mn.ppr_compose=#{params.pprCompose}
    
    
        and mn.ppr_model=#{params.pprModel}
    
    
        
            
                and (mn.ppr_model is null or mn.ppr_model = '')
            
            
                and mn.ppr_model in
                
                    #{pprModel}
                
            
        
    
    
        and mn.ppr_shape=#{params.pprShape}
    
    
        and mn.ppr_classify=#{params.pprClassify}
    
    
        and mn.ppr_approval=#{params.pprApproval}
    
    
        and mn.ppr_construction_year=#{params.pprConstructionYear}
    
    
        and mn.ppr_work_stage=#{params.pprWorkStage}
    
    
        and mn.ppr_Reserve_status=#{params.pprReserveStatus}
    
    
        
            
                and (mn.ppr_Reserve_status is null or mn.ppr_Reserve_status = '')
            
            
                and mn.ppr_Reserve_status in
                
                    #{pprReserveStatus}
                
            
        
    

    
        and mn.ppr_Reserve_stage=#{params.pprReserveStage}
    
    
        
            
                and (mn.ppr_Reserve_stage is null or mn.ppr_Reserve_stage = '')
            
            
                and mn.ppr_Reserve_stage in
                
                    #{pprReserveStage}
                
            
        
    

    
        and mn.state=#{params.state}
    
    
        
            
                and (mn.state is null or mn.state = '')
            
            
                and mn.state in
                
                    #{state}
                
            
        
    

    
        and mn.ppr_manager_unit=#{params.pprManagerUnit}
    
    
        and mn.ppr_business_unit=#{params.pprBusinessUnit}
    
    
        and TO_CHAR(mn.create_time, 'YYYY-MM-DD')=#{params.createTimeStr}
    
    
        and TO_CHAR(mn.ppr_Plan_Time, 'YYYY-MM')=#{params.pprPlanTimeStr}
    

    
        and mn.ppr_Reserve_cpy=#{params.pprReserveCpy}
    
    
        and INSTR(mn.create_uname,#{params.createUname})
    
    
        
            
                and (mn.create_uname is null or mn.create_uname = '')
            
            
                and mn.create_uname in
                
                    #{createUname}
                
            
        
    
    
        and INSTR(mn.ppr_name,#{params.pprName})
    
    
        
            
                and (mn.ppr_name is null or mn.ppr_name = '')
            
            
                and mn.ppr_name in
                
                    #{pprName}
                
            
        
    
    
        and mn.ppr_Rough in
        
            #{pprRough}
        
    
    
        and INSTR(mn.ppr_manager_dep,#{params.pprManagerDep})
    
    
        and INSTR(mn.ppr_manager_dep_name,#{params.pprManagerDepName})
    
    
        
            
                and (mn.ppr_manager_dep_name is null or mn.ppr_manager_dep_name = '')
            
            
                and mn.ppr_manager_dep_name in
                
                    #{pprManagerDepName}
                
            
        
    

    
        
            
                and likeCname(#{params.pprManagerUnitName},c1.C_Id)=true
            
            
                and INSTR(d1.d_name,#{params.pprManagerUnitName})
            
        
    
    
        and d1.d_name in
        
            #{pprManagerUnitName}
        
    

    
        
            
                and likeCname(#{params.pprBusinessUnitName},c2.C_Id)=true
            
            
                and INSTR(c2.c_name,#{params.pprBusinessUnitName})
            
        
    
    
        
            
                and likeCname(#{params.pprReserveCpyName},c3.C_Id)=true
            
            
                and INSTR(c3.c_name,#{params.pprReserveCpyName})
            
        
    
    
        
            
                and (c3.c_name is null or c3.c_name = '')
            
            
                and c3.c_name in
                
                    #{pprReserveCpyName}
